from typing import Union, Optional, Any

import requests
from requests.exceptions import (
    HTTPError,
    ConnectionError
)
import os
import uuid

from taf.vran.vdu.enb.rest.utilities.token_storage import TokenStorage
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails
from taf.vran.vdu.enb.rest.utilities.logger import (
    log_sending_message,
    log_received_response,
)
from taf.vran.vdu.enb.rest.exceptions import (
    APIRequestError,
    RequestTimeoutError
)
from taf.vran.vdu.enb.rest.utilities.headers import Headers


class HttpClient:
    def __init__(self, connection_details: ConnectionDetails) -> None:
        self.base_url = ""
        self.connection_details = connection_details
        self.username = connection_details.username
        self.password = connection_details.password
        self.token_storage = TokenStorage(connection_id=self.connection_details.connection_id)
        self.disable_logging = (
            os.getenv("TAF_LTE_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
        )
        self.headers = Headers()

    def send_request(
        self,
        method: str,
        endpoint: str,
        headers: Optional[dict] = None,
        data: Union[None, dict, str] = None,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        log_payload: bool = True,
        verify: bool = False,
        timeout: Optional[int] = None
    ) -> Any:
        """
        Sends request to the given endpoint.

        :param str method: HTTP method. Available options: "GET", "POST", "PUT", "PATCH", "DELETE".
        :param str endpoint: Endpoint to send the request to without base url, for example: "/login".
        :param dict headers: Headers to be sent with the request. For example: {"Content-Type": "application/json"}.
                             Defaults to None.
        :param Union[str, dict] data: Data to be sent with the request. Defaults to None.
        :param dict params: Query parameters to be sent with the request. For example: {"key": "value"}.
                            Defaults to None.
        :param dict json: JSON data to be sent with the request. Defaults to None.
        :param bool log_payload: If True, request payload is logged. Defaults to True.
        :param bool verify: If True, SSL certificate is verified. If False, SSL certificate is not verified.
                            Defaults to False.
        :param int timeout: timeout for request, for example 30. Defaults to None

        :raises APIRequestError: If the response status code is not 2xx.
        :raises RequestTimeoutError: If connection error occurs

        :returns: request response
        :rtype: Union[dict, bytes]
        """
        request_id = uuid.uuid4()
        headers = self._construct_headers(headers=headers)
        url = self.base_url + endpoint

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=url,
                params=params,
                data=data,
                headers=headers,
                method=method,
                json=json,
                log_payload=log_payload,
                connection_id=self.connection_details.connection_id,
            )

        try:
            response = requests.request(
                method=method,
                url=url,
                headers=headers,
                data=data,
                params=params,
                json=json,
                verify=verify,
                timeout=timeout
            )

        except ConnectionError as e:
            raise RequestTimeoutError(url=url) from e

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=url,
                method=method,
                connection_id=self.connection_details.connection_id,
            )

        try:
            response.raise_for_status()

        except HTTPError as e:
            raise APIRequestError(url=url, method=method, response=e.response) from e

        return self._process_response(response)

    @staticmethod
    def _process_response(response: requests.Response) -> Union[dict, bytes]:
        if (response.headers["Content-Type"] == "application/json") and (
            len(response.content) > 0
        ):
            return response.json()
        else:
            return response.content

    def _construct_headers(self, headers: Union[None, dict]) -> dict:
        return {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            **(headers or {}),
        }
